/** Starts the periodic heartbeat. `.unref()`'d so a live heartbeat can never
 *  keep the process alive on its own — `withApplyLock` guarantees it is
 *  always `clearInterval`'d (success or throw) before returning, but the
 *  `unref` is a second, independent safety net. */
function startApplyLockHeartbeat(): ReturnType<typeof setInterval> {
  const timer = setInterval(() => {
    void touchApplyLock();
  }, APPLY_LOCK_HEARTBEAT_MS);
  timer.unref?.();
  return timer;
}

/**
 * Acquires the dedicated `evals-apply.lock`, runs `fn` under a periodic mtime
 * heartbeat, then ALWAYS stops the heartbeat and releases the lock — success
 * OR throw, every exit path. The single place `applyProposal`/`revertProposal`/
 * `refreshBeforeSha` go through for this discipline (previously each
 * hand-rolled its own `acquireApplyLock` + `try { … } finally { release }`,
 * with no heartbeat at all — see `APPLY_LOCK_STALE_MS`'s docstring); factored
 * once so the three call sites cannot drift apart on it.
 */
async function withApplyLock<T>(label: string, fn: () => Promise<T>): Promise<T> {
  const lock = await acquireApplyLock(label);
  if (!lock.acquired) {
    throw new ApplyLockBusyError(lock.reason ?? 'verrou indisponible');
  }
  const heartbeat = startApplyLockHeartbeat();
  try {
    return await fn();
  } finally {
    clearInterval(heartbeat);
    await releaseApplyLock();
  }
}

