test('scope-lint meta-govern : chemins réalistes de SON PROPRE clone -> PASSENT (fix #4)', async () => {
  await importStore();
  const root = await freshRoot();
  const bareDir = await initBareRepo();
  const date = todayUtcDate();
  const results = {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    results: [
      {
        kind: 'improvementDiff',
        skill: 'meta-govern',
        // `meta-govern`'s clone IS the repo root (pas de préfixe `meta-govern/`
        // comme pour un skill générique du monorepo claude-skills) — voir
        // apply.ts "Chemin B".
        changedPaths: ['agents/architect.md', 'templates/rules/example.md', 'SKILL.md'],
      },
    ],
  };
  await pushBranch(bareDir, `results/${date}`, { 'results.json': JSON.stringify(results, null, 2) });

  // Rail non câblé dans ce test (pas de WORKSTATION_METAGOVERN_*) : passé le
  // scope-lint (l'assertion de ce test), le chemin gate+proposal échoue et
  // retombe sur un chip — voir la note sur VERDICT: IMPORTED_WITH_GAPS dans
  // le test dédié à ce repli plus haut dans ce fichier.
  const { stdout } = await run(root, ['import', '--from', bareDir]);
  expect(stdout).not.toContain('REJETÉ');
  expect(stdout).toContain('VERDICT: IMPORTED_WITH_GAPS');

  const chips = await chipStore.listChips();
  expect(chips.some((c) => c.title.includes('meta-govern'))).toBe(true);
});

